X = np.array([0., .5, 1.3, 2., 2.2, 3.1, 4., 5.5])
Y = np.sin(X)
Y2 = np.vstack((np.sin(X), np.cos(X) * 2.0, X ** 2))
XQ = np.array([-0.7, 0.0, 0.25, 1.0, 2.1, 3.1, 4.9, 5.5, 6.3])
XIN = np.array([0.0, 0.25, 1.0, 2.1, 3.1, 4.9, 5.5])

# ---------------------------------------------------------------- interp1d
for kind in ['linear', 'nearest', 'nearest-up', 'zero', 'slinear', 'quadratic', 'cubic', 'previous', 'next']:
    f = I.interp1d(X, Y, kind=kind, bounds_error=False, fill_value='extrapolate')
    check(f'i1d_{kind}_ext', f(XQ))
    check(f'i1d_{kind}_in', I.interp1d(X, Y, kind=kind)(XIN))
check('i1d_fill', I.interp1d(X, Y, bounds_error=False, fill_value=-9.0)(XQ))
check('i1d_fill2', I.interp1d(X, Y, bounds_error=False, fill_value=(-1.0, 7.0))(XQ))
check('i1d_nan', I.interp1d(X, Y, bounds_error=False)(XQ))
r = I.interp1d(X, Y2, kind='cubic', axis=1)(XIN)
assert r.shape == (3, 7)
check('i1d_axis', r)
check('i1d_axis0', I.interp1d(X, Y2.T, axis=0)(XIN))
check('i1d_unsorted', I.interp1d(X[::-1].copy(), Y[::-1].copy())(XIN))
assert abs(I.interp1d(X, Y)(1.0) - E['i1d_linear_in'][2]) < 1e-14
raises('i1d_bounds', lambda: I.interp1d(X, Y)(6.0))
raises('i1d_bounds_lo', lambda: I.interp1d(X, Y)(np.array([-1.0])))
raises('i1d_kind', lambda: I.interp1d(X, Y, kind='bogus'))
raises('i1d_extrap_raise', lambda: I.interp1d(X, Y, bounds_error=True, fill_value='extrapolate'))
raises('i1d_short', lambda: I.interp1d(X[:3], Y[:3], kind='cubic'))

# ---------------------------------------------------------------- CubicSpline
for bc in ['not-a-knot', 'natural', 'clamped']:
    cs = I.CubicSpline(X, Y, bc_type=bc)
    check(f'cs_{bc}', cs(XQ))
    check(f'cs_{bc}_d1', cs(XQ, 1))
    check(f'cs_{bc}_d2', cs(XQ, 2))
    check(f'cs_{bc}_int', [cs.integrate(-0.5, 4.4), cs.integrate(5.0, 1.0)])
check('cs_custom', I.CubicSpline(X, Y, bc_type=((1, 0.3), (2, -1.0)))(XQ))
XP = np.linspace(0, 2 * np.pi, 9)
YP = np.sin(XP)
YP[8] = YP[0]
csp = I.CubicSpline(XP, YP, bc_type='periodic')
check('cs_periodic', csp(np.array([-1.0, 0.3, 2.0, 7.5, 13.0])))
check('cs_periodic_int', [csp.integrate(0.5, 11.0)])
check('cs_noext', I.CubicSpline(X, Y, extrapolate=False)(XQ))
r2 = I.CubicSpline(X, Y2, axis=1)(XIN)
assert r2.shape == (3, 7)
check('cs_2d', r2)
check('cs_3pt', I.CubicSpline(X[:3], Y[:3])(XQ))
check('cs_2pt', I.CubicSpline(X[:2], Y[:2])(XQ))
cs = I.CubicSpline(X, Y)
check('cs_deriv', cs.derivative(2)(XQ))
check('cs_anti', cs.antiderivative()(XQ))
check('cs_anti2', cs.antiderivative(2)(XQ))
check('cs_roots', cs.roots(), 1e-9, 1e-9)
check('cs_solve', cs.solve(0.5), 1e-9, 1e-9)
check('cs_c', cs.c)
assert isinstance(cs(1.0), float)
raises('cs_periodic_bad', lambda: I.CubicSpline(X, Y, bc_type='periodic'))
raises('cs_bad_bc', lambda: I.CubicSpline(X, Y, bc_type='foo'))
raises('cs_unsorted', lambda: I.CubicSpline(X[::-1].copy(), Y))
raises('cs_len', lambda: I.CubicSpline(X[:5], Y))
raises('cs_order', lambda: I.CubicSpline(X, Y, bc_type=((3, 0.0), (1, 0.0))))

# ---------------------------------------------------------------- Pchip / Akima
check('pchip', I.PchipInterpolator(X, Y)(XQ))
check('pchip_d1', I.PchipInterpolator(X, Y)(XQ, 1))
YM = np.array([0., 1., 1., 3., 2., 2.5, 2.5, 0.])
check('pchip_mono', I.PchipInterpolator(X, YM)(XQ))
check('pchip_2d', I.PchipInterpolator(X, Y2, axis=1)(XIN))
check('pchip_interp', I.pchip_interpolate(X, YM, XIN, der=1))
check('akima', I.Akima1DInterpolator(X, YM)(XQ))
check('makima', I.Akima1DInterpolator(X, YM, method='makima')(XQ))
check('akima_ext', I.Akima1DInterpolator(X, YM, extrapolate=True)(XQ))
check('akima_2d', I.Akima1DInterpolator(X, Y2, axis=1)(XIN))
check('hermite', I.CubicHermiteSpline(X, Y, np.cos(X))(XQ))
raises('akima_method', lambda: I.Akima1DInterpolator(X, Y, method='foo'))

# ---------------------------------------------------------------- PPoly
pp = I.PPoly(np.array([[1., 2.], [0., -1.], [3., 0.5]]), np.array([0., 1., 3.]))
check('ppoly', pp(XQ))
check('ppoly_int', [pp.integrate(-1.0, 2.5), pp.integrate(0.5, 4.0, extrapolate=False)])
check('ppoly_noext', I.PPoly(pp.c, pp.x, extrapolate=False)(XQ))
raises('ppoly_len', lambda: I.PPoly(np.ones((2, 3)), np.array([0., 1., 3.])))

# ---------------------------------------------------------------- B-splines
for k in [1, 2, 3, 4, 5]:
    b = I.make_interp_spline(X, Y, k=k)
    check(f'mis_{k}', b(XQ))
    check(f'mis_{k}_t', b.t)
    check(f'mis_{k}_c', b.c)
    check(f'mis_{k}_d1', b(XQ, nu=1))
    check(f'mis_{k}_int', [b.integrate(-0.5, 4.4), b.integrate(-0.5, 4.4, extrapolate=False)])
check('mis_0', I.make_interp_spline(X, Y, k=0)(XIN))
check('mis_nat', I.make_interp_spline(X, Y, bc_type='natural')(XQ))
check('mis_clamp', I.make_interp_spline(X, Y, bc_type='clamped')(XQ))
check('mis_bc', I.make_interp_spline(X, Y, k=5, bc_type=([(1, 0.5), (2, 0.0)], [(1, -1.0), (2, 1.0)]))(XQ), 1e-10, 1e-10)
check('mis_2d', I.make_interp_spline(X, Y2, axis=1)(XIN))
check('mis_per', I.make_interp_spline(XP, YP, bc_type='periodic')(np.array([-1.0, 0.3, 2.0, 7.5])))
check('mis_per5', I.make_interp_spline(XP, YP, k=5, bc_type='periodic')(np.array([-1.0, 0.3, 2.0, 7.5])))
b = I.make_interp_spline(X, Y)
check('bs_der2', b.derivative(2)(XQ))
check('bs_anti', b.antiderivative()(XQ))
check('bs_anti_t', b.antiderivative().t)
check('bs_noext', b(XQ, extrapolate=False))
be = I.BSpline.basis_element([0., 1., 2., 4.])
check('bs_basis', be(np.array([-0.5, 0.0, 0.5, 1.5, 3.0, 4.0])))
check('bs_basis_noext', I.BSpline.basis_element([0., 1., 2., 4.], extrapolate=False)(np.array([-0.5, 0.5, 3.0, 4.5])))
bs = I.BSpline(np.array([0., 0., 0., 1., 2., 3., 3., 3.]), np.array([1., -1., 2., 0.5, 3.]), 2)
check('bs_manual', bs(XQ))
check('bs_manual_int', [bs.integrate(0.2, 2.7), bs.integrate(-1.0, 5.0)])
check('bs_design', I.BSpline.design_matrix(np.array([0.0, 0.7, 1.5, 3.0]), bs.t, 2))
raises('mis_dup', lambda: I.make_interp_spline(np.array([0., 1., 1., 2.]), np.ones(4)))
raises('mis_k1bc', lambda: I.make_interp_spline(X, Y, k=1, bc_type='natural'))
raises('mis_nbc', lambda: I.make_interp_spline(X, Y, k=5, bc_type='natural'))
raises('bs_knots', lambda: I.BSpline(np.array([0., 1.]), np.array([1., 2.]), 3))

# ---------------------------------------------------------------- FITPACK
for k in [1, 2, 3, 5]:
    tck = I.splrep(X, Y, k=k)
    check(f'splrep_{k}_t', tck[0])
    check(f'splrep_{k}_c', tck[1])
    check(f'splev_{k}', I.splev(XQ, tck))
    check(f'splev_{k}_d1', I.splev(XQ, tck, der=1))
tck = I.splrep(X, Y)
check('splev_ext1', I.splev(XQ, tck, ext=1))
check('splev_ext3', I.splev(XQ, tck, ext=3))
check('splint', [I.splint(0.3, 4.2, tck), I.splint(-1.0, 9.0, tck), I.splint(4.0, 1.0, tck)])
td = I.splder(tck)
check('splder_t', td[0])
check('splder_c', td[1])
check('splantider_c', I.splantider(tck, 2)[1])
assert isinstance(interpolate.splev(1.0, tck), float)
raises('splev_ext2', lambda: I.splev(XQ, tck, ext=2))
raises('splev_der', lambda: I.splev(XQ, tck, der=4))
raises('splrep_m', lambda: I.splrep(X[:3], Y[:3], k=3))
raises('splrep_k', lambda: I.splrep(X, Y, k=6))

# ---------------------------------------------------------------- regular grid
g1 = np.array([0., 1., 2.5, 4.])
g2 = np.array([-1., 0., 0.5, 2., 3.])
V = np.empty((4, 5))
for i in range(4):
    for j in range(5):
        V[i, j] = np.sin(g1[i]) * np.cos(g2[j]) + g1[i] * g2[j]
pts = np.array([[0.3, -0.5], [2.5, 0.25], [3.9, 2.9], [1.0, 0.0], [0.0, 3.0]])
check('rgi_lin', I.RegularGridInterpolator((g1, g2), V)(pts))
check('rgi_near', I.RegularGridInterpolator((g1, g2), V, method='nearest')(pts))
ptsx = np.array([[-0.5, 0.0], [1.0, 3.5], [2.0, 1.0]])
check('rgi_fill', I.RegularGridInterpolator((g1, g2), V, bounds_error=False, fill_value=-5.0)(ptsx))
check('rgi_extrap', I.RegularGridInterpolator((g1, g2), V, bounds_error=False, fill_value=None)(ptsx))
check('rgi_desc', I.RegularGridInterpolator((g1[::-1].copy(), g2), np.flip(V, axis=0).copy())(pts))
g3 = np.array([0., 1., 3.])
V3 = np.arange(60, dtype=float).reshape((4, 5, 3)) ** 1.5
check('rgi_3d', I.RegularGridInterpolator((g1, g2, g3), V3)(np.array([[0.3, -0.5, 2.0], [3.0, 2.2, 0.4]])))
rt = I.RegularGridInterpolator((g1, g2), V3)(pts)
assert rt.shape == (5, 3)
check('rgi_trail', rt)
check('interpn', I.interpn((g1, g2), V, pts))
check('interpn_near', I.interpn((g1, g2), V, pts, method='nearest'))
rm = I.RegularGridInterpolator((g1, g2), V)((np.array([[0.5], [1.5]]), np.array([[0.0, 1.0, 2.5]])))
assert rm.shape == (2, 3)
check('rgi_mesh', rm)
raises('rgi_oob', lambda: I.RegularGridInterpolator((g1, g2), V)(ptsx))
raises('rgi_method', lambda: I.RegularGridInterpolator((g1, g2), V, method='foo'))
raises('rgi_dim', lambda: I.RegularGridInterpolator((g1, g2), V)(np.array([[1.0, 2.0, 3.0]])))
raises('interpn_method', lambda: I.interpn((g1, g2), V, pts, method='foo'))

if FAILS[0] == 0:
    print('interpolate ok')
